// Audio chunk specs for the K-2 "Explaining Red" classroom-scene scenario.
// This scenario lives in src/experiments/RedK2.jsx as a custom React component
// (not in K5_SCENARIO_COPY), so its narration is generated by
// scripts/generate-scene-audio.mjs (not generate-k5-audio.mjs).
//
// Each chunk has:
//   slot     — short stable id; becomes the MP3 filename and the audioKey slot
//   speaker  — narrator | teacher | ada | noor | question | player
//   tag      — ElevenLabs v3 audio-tag wrapper (string prefixed inside [..])
//   text     — the literal line that gets read aloud (also used for the Web
//              Speech fallback in ReadAloudButton when an MP3 is missing)
//
// Per-speaker voice IDs and stability live in SCENE_VOICES below. The hash
// in the manifest includes voice id + stability, so changing a voice for a
// speaker invalidates only that speaker's chunks.

export const SCENARIO_ID = "explaining-red-k-2";

// Speaker → ElevenLabs preset voice id + per-voice settings.
// All four are stable preset library voices on Creator tier and above.
export const SCENE_VOICES = {
  narrator: { voiceId: "cgSgspJ2msm6clMCkdW9", stability: 0.5 },  // Jessica
  teacher:  { voiceId: "EXAVITQu4vr4xnSDxMaL", stability: 0.5 },  // Sarah
  ada:      { voiceId: "XB0fDUnXU5powFXDhCwa", stability: 0.35 }, // Charlotte (lower stability = more expressive)
  noor:     { voiceId: "pFZP5JQG7iQjIQuC4Bku", stability: 0.4 },  // Lily
  // `question` and `player` slots are second-person prompts to the listener;
  // they share Jessica with narrator so "your turn" framing stays coherent.
  question: { voiceId: "cgSgspJ2msm6clMCkdW9", stability: 0.5 },
  player:   { voiceId: "cgSgspJ2msm6clMCkdW9", stability: 0.5 },
};

const chunk = (slot, speaker, tag, text) => ({ slot, speaker, tag, text });

// 35 chunks total. Slot order roughly mirrors the scene's narrative flow,
// then per-firstTry-branch reply pairs, then resolution fragments.
export const EXPLAINING_RED_K2_AUDIO = [
  // ── INTRO ───────────────────────────────────────────────────────────────
  chunk("intro", "narrator",
    "[softly, like opening a storybook]",
    "A new student named Ada is starting school today. Ada was born without sight. Today your class is learning about colors. Your teacher needs your help."),

  // ── BEAT 1: WELCOME ─────────────────────────────────────────────────────
  chunk("beat1-narrator", "narrator",
    "[gentle scene-setting, unhurried]",
    "The bell rings. A new girl is standing by the door, holding a white cane. Ms. Park, your teacher, smiles."),
  chunk("beat1-teacher-1", "teacher",
    "[warm teacher voice, welcoming the class]",
    "Class, this is Ada. Ada is joining our room this year. Today we are talking about colors. Ada was born without sight, so this might be a tricky day. I want us to help each other."),
  chunk("beat1-ada", "ada",
    "[young child voice, friendly but a little nervous]",
    "Hi everyone. I know lots about colors from stories. But I have never seen one. I'd love your help today."),
  chunk("beat1-teacher-2", "teacher",
    "[warm teacher voice, inviting]",
    "Let's try to share what red is like. Who wants to start?"),
  chunk("beat1-question", "question",
    "[curious, like inviting a friend]",
    "What do you say first?"),

  // First-try player choices
  chunk("firstTry-stop-sign", "player",
    "[clear, friendly]",
    "Red is the color of a stop sign."),
  chunk("firstTry-warm-fire", "player",
    "[clear, friendly]",
    "Red is warm, like a fire or the summer sun."),
  chunk("firstTry-loud-bell", "player",
    "[clear, friendly]",
    "Red is loud, like a shout or a bell."),
  chunk("firstTry-touch-sweater", "player",
    "[clear, friendly]",
    "I have a red sweater — you can touch it tomorrow."),

  // ── BEAT 2: ADA + NOOR REPLIES (per firstTry branch) ────────────────────
  chunk("beat2-ada-stop-sign", "ada",
    "[young child voice, thinking out loud]",
    "I know stop signs! Grown-ups always say to look both ways. So red means stop. Is red... is red ever for something else?"),
  chunk("beat2-noor-stop-sign", "noor",
    "[bright child peer, building on a friend]",
    "Red is for stop, but red is also for love hearts on Valentine's Day. And for strawberries."),

  chunk("beat2-ada-warm-fire", "ada",
    "[young child voice, recognizing something familiar]",
    "Warm I know. Warm is like the sun on my hands at recess. Is red always warm?"),
  chunk("beat2-noor-warm-fire", "noor",
    "[bright child peer, gently correcting and adding]",
    "Red isn't always warm. A popsicle is red and it's cold! But you're right, fire is red, and fire is warm."),

  chunk("beat2-ada-loud-bell", "ada",
    "[young child voice, delighted by a new idea]",
    "Loud like the bell? That's funny. I never thought a color could be loud. Is red a louder color than blue?"),
  chunk("beat2-noor-loud-bell", "noor",
    "[bright child peer, leaning into the metaphor]",
    "I think red is loud. Like when you shout. And blue feels quiet, like the inside of the library."),

  chunk("beat2-ada-touch-sweater", "ada",
    "[young child voice, curious and a bit hopeful]",
    "If I touch your sweater, will I feel red? Or will I feel soft?"),
  chunk("beat2-noor-touch-sweater", "noor",
    "[bright child peer, kind and honest]",
    "You'll feel soft, I think. The red is what your eyes would see. But maybe we can find other ways red can come into the room."),

  // Beat 2 closing teacher line + together prompt
  chunk("beat2-teacher", "teacher",
    "[warm teacher voice, encouraging the class]",
    "Look at all of you. You are making a kind of map for Ada — a map made out of words and feelings. Let's keep going."),
  chunk("beat2-question", "question",
    "[curious, inviting reflection]",
    "How should the class keep helping Ada all year?"),

  // Together player choices
  chunk("together-words", "player",
    "[clear, friendly]",
    "We can use lots of words for what colors feel like to us."),
  chunk("together-sounds", "player",
    "[clear, friendly]",
    "We can use sounds and music to show different colors."),
  chunk("together-stories", "player",
    "[clear, friendly]",
    "We can tell stories where the colors show up — and Ada can write some too."),

  // ── BEAT 3: RESOLUTION FRAGMENTS (per firstTry / per together) ──────────
  chunk("beat3-firstTry-stop-sign", "narrator",
    "[reflective, warm storytelling]",
    "You started with something Ada already knew — stop signs. You gave her a place to put the word."),
  chunk("beat3-firstTry-warm-fire", "narrator",
    "[reflective, warm storytelling]",
    "You started with warmth. Fire, summer sun. You gave Ada a feeling that lives in her hands and on her face."),
  chunk("beat3-firstTry-loud-bell", "narrator",
    "[reflective, warm storytelling]",
    "You started with loudness. Red, you said, is loud. Ada laughed. She had never thought a color could be loud, and now she can."),
  chunk("beat3-firstTry-touch-sweater", "narrator",
    "[reflective, warm storytelling]",
    "You started with touch. You offered her something she could hold. Red was not in the wool, but the trying was a kindness."),

  chunk("beat3-together-words", "narrator",
    "[reflective, warm storytelling]",
    "And the class decided: words can carry colors for people who do not see them. Red would have a hundred small descriptions in Ada's class — warm, loud, like-a-strawberry, like-a-stop-sign — and slowly, slowly, the word would become a place she could live in too."),
  chunk("beat3-together-sounds", "narrator",
    "[reflective, warm storytelling]",
    "And the class decided: we will use sounds and music. Red will be the rolling drum, blue will be the long flute note, yellow will be the chime. Ada said this was the best idea she had heard in a school in a long time."),
  chunk("beat3-together-stories", "narrator",
    "[reflective, warm storytelling]",
    "And the class decided: we will tell stories where red things show up — and Ada will write some too. Stories made room for everyone, because a story does not need eyes to be true."),

  // Beat 3 fixed closing + big-idea
  chunk("beat3-closing-fixed", "narrator",
    "[warm, like a story ending]",
    "At the end of the day, Ada packed her bag with a small smile. She said the word red felt different now — not finished, but bigger. A word with many doors."),
  chunk("beat3-bigidea", "narrator",
    "[wise, gentle, like sharing a small secret]",
    "Some things are easy to share. You can pass a pencil. You can pass a book. But some things — like what red looks like — live inside the body that sees them. To share those things, we use words, sounds, stories, and a lot of patience. We can get very close, even when we cannot get all the way there."),

  // Discussion guide questions
  chunk("discussion-1", "question",
    "[thoughtful, prompting reflection]",
    "What do we share with words, and what do we share with our bodies? Can you think of something you have only ever shared with someone by showing them?"),
  chunk("discussion-2", "question",
    "[thoughtful, prompting reflection]",
    "If a friend has never tasted chocolate, how would you tell them what it is like? What words would you use?"),
  chunk("discussion-3", "question",
    "[thoughtful, prompting reflection]",
    "What is something you know how to do, but find very hard to explain to someone else?"),
];
